P=Path(__file__).resolve().parents[1]/'public'
for lang in ['hi','en']:
 hi=lang=='hi';L=lambda a,b:a if hi else b;home=L('index.html','english.html');url=L('free-tools.html','free-tools-english.html');alt=L('free-tools-english.html','free-tools.html');title=L('निःशुल्क अंकज्योतिष उपकरण','Free numerology tools')
 body=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | AstroVedansh®</title><meta name="description" content="{L('जन्मतिथि से मूलांक, भाग्यांक, अंकज्योतिष सारणी और आयु की सरल गणना करें।','Calculate your birth number, full-date number, numerology grid and age from your date of birth.')}"><link rel="canonical" href="https://courses.astrovedansh.org/{url}"><link rel="alternate" hreflang="hi" href="https://courses.astrovedansh.org/free-tools.html"><link rel="alternate" hreflang="en" href="https://courses.astrovedansh.org/free-tools-english.html"><link rel="stylesheet" href="journal.css"><link rel="stylesheet" href="free-tools.css"><link rel="stylesheet" href="promotion.css"><link href="https://fonts.googleapis.com/css2?family=Noto+Sans+Devanagari:wght@400;500;600;700&display=swap" rel="stylesheet"></head><body><a class="journal-skip" href="#main">{L('मुख्य सामग्री पर जाएँ','Skip to content')}</a><header class="j-header"><div class="j-container"><a class="j-brand" href="{home}"><img src="assets/astrovedansh-logo.webp" width="44" height="44" alt=""><span>Astro<strong>Vedansh</strong><sup>®</sup></span></a><nav><a class="j-language" href="{alt}" lang="{L('en','hi')}">{L('English','हिन्दी')}</a><a href="{home}#courses">{L('पाठ्यक्रम','Courses')} →</a></nav></div></header><main class="tools-wrap" id="main"><div class="tools-intro"><span class="j-eyebrow">{L('छोटी गणना। सीखने की नई शुरुआत।','A SMALL CALCULATION. A NEW WAY TO LEARN.')}</span><h1>{L('अपनी जन्मतिथि के<br>अंक समझें।','Understand the numbers<br>in your birth date.')}</h1><p>{L('मूलांक, भाग्यांक, आपकी अंक-सारणी, सूर्य–चंद्र राशि और पूरा हुआ आयु-वर्ष—एक ही जगह। गणना के साथ उसका तरीका भी समझें।','Explore your birth number, full-date number, number grid, Sun and Moon signs, and completed age. See the calculation, not just the answer.')}</p></div><form id="birth-form" class="tool-form"><div><label for="birth-date">{L('जन्मतिथि','Date of birth')}</label><input id="birth-date" type="date" min="1900-01-01" required aria-describedby="date-help tool-error"></div><div><label for="birth-time">{L('जन्म का समय · सूर्य और चंद्र राशि','Birth time · for Sun and Moon signs')}</label><input id="birth-time" type="time" aria-describedby="moon-input-help"></div><div><label for="birth-offset">{L('जन्म के समय UTC से अंतर (घंटे)','UTC offset at birth (hours)')}</label><input id="birth-offset" type="number" min="-12" max="14" step="0.25" value="5.5" required aria-describedby="moon-input-help"></div><button type="submit">{L('मेरी गणना करें','Calculate my numbers')} →</button><button type="reset">{L('फिर से शुरू करें','Reset')}</button></form><p class="tools-small" id="moon-input-help">{L('भारत में जन्म के लिए 5.5 रखें। विदेश में जन्म हो तो जन्म-स्थान पर उस तारीख का UTC अंतर भरें, जिसमें लागू ग्रीष्मकालीन समय भी शामिल हो। समय न मालूम हो तो खाली छोड़ें; मूलांक और भाग्यांक फिर भी मिलेंगे।','For births in India, keep 5.5. For other countries, enter the UTC offset in effect at the birthplace on that date, including daylight saving if applicable. Leave time blank if unknown; numerology results will still work.')}</p><p class="tools-small" id="date-help">{L('गणना इसी ब्राउज़र में होती है। जन्मतिथि हमारे सर्वर पर भेजी या सहेजी नहीं जाती।','Calculations run in this browser. Your birth date is not sent to or stored on our server.')}</p><button class="tool-action" type="button" id="demo-date">{L('23 सितंबर 1996 का उदाहरण देखें','Try the 23 September 1996 example')}</button><p id="tool-error" class="tool-error" role="alert"></p><p id="tool-status" role="status"></p><section class="tool-output" id="tool-results" hidden><h2 tabindex="-1" id="results-title">{L('आपकी गणना','Your results')}</h2><div class="tool-layout"><article class="tool-card"><h3>{L('मूलांक और भाग्यांक','Birth and full-date numbers')}</h3><div class="tool-numbers"><div class="tool-number">{L('मूलांक','Birth number')}<strong id="mulank-value"></strong><small id="mulank-math"></small></div><div class="tool-number">{L('भाग्यांक','Full-date number')}<strong id="bhagyank-value"></strong><small id="bhagyank-math"></small></div></div><p id="short-reading"></p><p class="tools-small">{L('यह पारंपरिक अंकज्योतिष का संक्षिप्त परिचय है, निश्चित भविष्यवाणी या वैज्ञानिक व्यक्तित्व परीक्षण नहीं।','This is a brief traditional numerology interpretation, not a guaranteed prediction or scientific personality test.')}</p></article><article class="tool-card"><h3>{L('आपकी जन्मतिथि की अंक-सारणी','Your birth-date number grid')}</h3><div id="birth-grid" class="birth-grid" role="group" aria-label="{L('अंक-सारणी','Number grid')}"></div><p class="tools-small" id="grid-digits"></p><p class="tools-small" id="grid-summary"></p><p class="tools-small">{L('खाली स्थान का अर्थ है कि उस अंक का उपयोग सारणी में नहीं हुआ। इससे अपने-आप कोई दोष सिद्ध नहीं होता।','An empty cell means that digit was not used in this grid. It does not automatically establish a flaw.')}</p></article><article class="tool-card"><h3>{L('वैदिक सूर्य राशि · लाहिड़ी अनुमान','Vedic Sun sign · approximate Lahiri')}</h3><strong id="sun-value" class="tool-sign"></strong><p id="sun-note"></p><p class="tools-small">{L('सूर्य और चंद्र राशि दोनों यहाँ निरयन पद्धति से हैं। पश्चिमी सूर्य राशि इससे अलग हो सकती है।','Both Sun and Moon signs here use the sidereal zodiac. Your Western Sun sign may differ.')}</p><a class="j-back" href="https://play.google.com/store/apps/details?id=com.FinalAstroTry.app" target="_blank" rel="noopener noreferrer">{L('AstroTry पर कुंडली देखें','Explore charts in AstroTry')} ↗</a></article><article class="tool-card"><h3>{L('वैदिक चंद्र राशि · लाहिड़ी अनुमान','Vedic Moon sign · approximate Lahiri')}</h3><strong id="moon-value" class="tool-sign"></strong><p id="moon-note"></p><p class="tools-small">{L('पृथ्वी के केंद्र से चंद्रमा की स्थिति पर आधारित गणना। राशि सीमा के पास पूरी कुंडली से पुष्टि करें।','Calculated from the Moon’s geocentric position. Confirm with a full chart near a sign boundary.')}</p></article><article class="tool-card"><h3>{L('पूरी हुई आयु','Completed age')}</h3><strong class="tool-sign" id="age-value"></strong><p>{L('आज की तारीख तक पूरे हुए वर्ष। यह आपके उपकरण की स्थानीय तारीख के अनुसार है।','Completed years as of today, using your device’s local date.')}</p><button class="tool-action" id="copy-results" type="button">{L('अंकज्योतिष परिणाम कॉपी करें','Copy numerology results')}</button><p id="copy-status" role="status" class="tools-small"></p></article></div></section><details class="tool-method"><summary>{L('गणना कैसे होती है?','How are these calculated?')}</summary><p>{L('मूलांक: केवल जन्म के दिन के अंकों को जोड़कर 1–9 तक घटाते हैं। भाग्यांक: पूरी दिन-माह-वर्ष जन्मतिथि के सभी अंक जोड़ते हैं; वर्ष का 19 इसमें हटाया नहीं जाता। 11, 22 और 33 भी यहाँ एक अंक तक घटते हैं।','Birth number: reduce the day of birth to 1–9. Full-date number: add every digit in the entire date, including all year digits, then reduce to 1–9. This method also reduces 11, 22 and 33.')}</p><p>{L('सारणी क्रम: 3–1–9 / 6–7–5 / 2–8–4। इस AstroVedansh अभ्यास-विधि में शून्य छोड़ते हैं और 1900–1999 जन्म-वर्ष का शुरुआती 19 हटाते हैं। 2000 के बाद के वर्षों के गैर-शून्य अंक पूरे लेते हैं। मूलांक और भाग्यांक को इस कच्ची जन्मतिथि-सारणी में दोबारा नहीं जोड़ते।','Grid order: 3–1–9 / 6–7–5 / 2–8–4. In this AstroVedansh practice method, omit zeros and the leading 19 for birth years 1900–1999. For years from 2000 onward, use all nonzero year digits. Do not add the calculated birth or full-date numbers back into this raw grid.')}</p><p>{L('अलग परंपराओं में सारणी या गणना की विधि अलग हो सकती है।','Other numerology traditions may use different grids or conventions.')}</p><p>{L('सूर्य और चंद्र राशि: Astronomy Engine की ग्रह स्थिति से समयानुसार लाहिड़ी अयनांश का अनुमान घटाया जाता है। जन्म-स्थान का सही समय-क्षेत्र जरूरी है; यहाँ लग्न या भावों की गणना नहीं होती।','Sun and Moon signs: Astronomy Engine planetary positions with an approximate date-adjusted Lahiri offset. The correct birthplace UTC offset is essential. This tool does not calculate the ascendant or houses.')}</p><a href="https://github.com/cosinekitty/astronomy" target="_blank" rel="noopener noreferrer">Astronomy Engine ↗</a></details><div class="tool-links"><a href="{L('journal.html','journal-english.html')}">{L('लेखों से ज्योतिष सीखें','Learn through articles')} →</a><a href="{L('numerology.html','numerology-english.html')}">{L('अंकज्योतिष पाठ्यक्रम देखें','Explore the numerology course')} →</a></div><noscript><p>{L('इन गणनाओं के लिए ब्राउज़र में JavaScript चालू करें।','Enable JavaScript in your browser to use these calculators.')}</p></noscript></main>{promotion('',lang)}<script src="vendor/astronomy-engine-2.1.19.min.js"></script><script type="module" src="free-tools.js"></script></body></html>'''
 (P/url).write_text(body)
